const editor=document.getElementById('editor'),form=document.getElementById('form');document.getElementById('add').onclick=()=>{resetRecording();resetBoard();resetResources();resetExplanation();form.reset();form.elements.details.disabled=false;form.elements.details.required=true;form.elements.due.value=key(dates[selected]);form.elements.teacher.value=activeTeacher()?.name||'';editor.showModal()};document.getElementById('cancel').onclick=()=>editor.close();editor.addEventListener('close',stopRecording);form.elements.kind.onchange=()=>{form.elements.details.required=form.elements.kind.value==='task';form.elements.details.disabled=form.elements.kind.value==='none'};
form.onsubmit=async e=>{e.preventDefault();if(recording||audioProcessing||starting||transcribing||ocrBusy||photosLoading||resourcesLoading||aiGenerating){alert('יש לעצור את ההקלטה ולהמתין להכנת קובץ השמע לפני השמירה.');return}if(role!=='teacher'||!teacherHasClass()||!teacherPermission('can_update_lessons'))return;const f=new FormData(form),kind=f.get('kind'),details=String(f.get('details')||'').trim(),teacher=String(f.get('teacher')).trim();if(!teacher||(kind==='task'&&!details)){alert('יש למלא שם מורה ופירוט משימה.');return}const r={updatedAt:new Date().toISOString(),classId:activeClassId(),teacherId:school.teacherId,completions:{},lesson:collectLessonSummary(form),explanation:collectExplanation(teacher),day:key(dates[selected]),subject:f.get('subject'),teacher,kind,details,due:f.get('due'),dueTime:f.get('dueTime'),audio:recordedAudio,resources:taskResources.map(r=>({...r})),photos:boardPhotos.map(p=>({src:p.src,name:p.name,caption:p.caption||''})),done:false};if(cloud.ready){try{await cloudSaveLesson(r)}catch(e){cloudMessage('שמירת העדכון נכשלה: '+e.message);return}}const original=records.find(x=>x.classId===r.classId&&x.day===r.day&&x.subject===r.subject);if(original&&original.kind===r.kind&&original.details===r.details){r.done=original.done;r.completedAt=original.completedAt||null;r.completions=original.completions||{}}const previous=records;records=records.filter(x=>!(x.classId===r.classId&&x.day===r.day&&x.subject===r.subject));records.push(r);if(!save()){records=previous;return}if(typeof emitLessonUpdate==='function')emitLessonUpdate(r);if(typeof trackUsage==='function'){trackUsage('lesson_updated');if(r.photos?.length&&JSON.stringify(r.photos)!==JSON.stringify(original?.photos))trackUsage('photo_attached');if(r.resources?.length&&JSON.stringify(r.resources)!==JSON.stringify(original?.resources))trackUsage('resource_attached');}editor.close();render()};
document.getElementById('summary').onclick=()=>{const c=document.getElementById('weeklyContent');c.replaceChildren();dates.forEach(d=>{const rs=classRecords().filter(r=>r.day===key(d)),tasks=rs.filter(r=>r.kind==='task');c.append(el('div',`${d.toLocaleDateString(siteLocale(),{weekday:'long'})}: ${tasks.filter(r=>r.done).length} מתוך ${tasks.length} משימות הוכנו · ${subjects.length-new Set(rs.map(r=>r.subject)).size} מקצועות ללא עדכון`,'side-row'));rs.forEach(r=>{if(r.lesson&&(r.lesson.summary||r.lesson.topic||r.lesson.concepts)){c.append(el('h3',r.subject));renderLessonSummary(c,r.lesson)}})});document.getElementById('weekly').showModal()};document.getElementById('closeSummary').onclick=()=>document.getElementById('weekly').close();let recorder=null,recording=false,recordedAudio=null,stream=null,recordTimer=null,session=0,starting=false,audioProcessing=false,transcribing=false;
const recordButton=document.getElementById('record'),recordStatus=document.getElementById('recordStatus'),preview=document.getElementById('recordPreview');
function stopRecording(){starting=false;if(recorder&&recorder.state==='recording'){audioProcessing=true;recorder.stop()}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}clearTimeout(recordTimer);recording=false;recordButton.textContent='🎙 התחלת הקלטה'}
function resetRecording(){session++;stopRecording();audioProcessing=false;recordedAudio=null;preview.hidden=true;preview.removeAttribute('src');document.getElementById('transcribe').hidden=true;recordStatus.textContent='אפשר להקליט עד 60 שניות. בדקו את התמלול לפני השמירה.'}
recordButton.onclick=async()=>{if(recording){stopRecording();return}if(starting||audioProcessing||transcribing)return;if(form.elements.kind.value==='none'){recordStatus.textContent='בחרו ״יש שיעורי בית״ כדי להקליט הוראות.';return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){recordStatus.textContent='הקלטה אינה זמינה כאן. פתחו דרך HTTPS או localhost בדפדפן תומך, או כתבו את ההוראות.';return}const current=++session;starting=true;recordButton.disabled=true;try{const mic=await navigator.mediaDevices.getUserMedia({audio:true});if(current!==session||!editor.open||!starting){mic.getTracks().forEach(t=>t.stop());return}stream=mic;const chunks=[];recorder=new MediaRecorder(mic);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const reader=new FileReader();reader.onload=()=>{if(current!==session)return;audioProcessing=false;recordedAudio=reader.result;preview.src=recordedAudio;preview.hidden=false;recordStatus.textContent+=' ההקלטה מוכנה להשמעה.';recordButton.disabled=false;document.getElementById('transcribe').hidden=false;transcribeAudio(current)};reader.onerror=()=>{if(current===session){audioProcessing=false;recordStatus.textContent='שמירת השמע נכשלה. אפשר לשמור את הטקסט או להקליט שוב.'}};reader.readAsDataURL(new Blob(chunks,{type:recorder.mimeType}))};recorder.start();recording=true;recordButton.textContent='■ עצירת הקלטה';recordStatus.textContent='מקליט…';recordStatus.textContent='מקליט… לאחר העצירה ההקלטה תתומלל במכשיר.';recordTimer=setTimeout(stopRecording,60000)}catch{recordStatus.textContent='לא ניתן לגשת למיקרופון. אפשר לאשר גישה בהגדרות הדפדפן או לכתוב את ההוראות.';stopRecording()}finally{starting=false;recordButton.disabled=false}};
const notified=new Set();
function deadline(r){return new Date(r.due+'T'+(r.dueTime||'08:00')).getTime()}
function renderAlerts(){document.getElementById('parentAlerts').hidden=role!=='parent';const box=document.getElementById('alerts');box.replaceChildren();const now=Date.now(),outstanding=classRecords().filter(r=>r.kind==='task'&&!r.done&&Number.isFinite(deadline(r))).sort((a,b)=>deadline(a)-deadline(b));if(!outstanding.length)box.append(el('p','אין משימות פתוחות כרגע ✓'));outstanding.forEach(r=>{const late=deadline(r)<=now,soon=deadline(r)-now<=3600000;const text=`${r.subject}: ${late?'מועד השיעור עבר והשיעורים לא סומנו כהוכנו':soon?'השיעור בעוד פחות משעה — טרם הוכן':'ממתין להכנה לפני השיעור'} · ${new Date(deadline(r)).toLocaleString(siteLocale())}`;box.append(el('p',text,late||soon?'notice':'meta'));const id=[activeStudentId(),r.classId,r.day,r.subject,r.due,r.dueTime,late?'late':'soon'].join('|');if(role==='parent'&&soon&&'Notification' in window&&Notification.permission==='granted'&&!notified.has(id)){try{new Notification('יש שיעורים — תזכורת להורה',{body:text});notified.add(id)}catch{}}})}
document.getElementById('enableAlerts').onclick=async()=>{const b=document.getElementById('enableAlerts');if(!('Notification' in window)){b.textContent='התראות מערכת אינן נתמכות — ההתראות מוצגות כאן';return}try{const permission=await Notification.requestPermission();b.textContent=permission==='granted'?'✓ התראות הופעלו כשהאפליקציה פתוחה':'לא אושרו התראות — אפשר לצפות בהן כאן';renderAlerts()}catch{b.textContent='הפעלת התראות דורשת דפדפן תומך וחיבור מאובטח'}};
setInterval(()=>{if(role==='parent')renderAlerts()},30000);window.addEventListener('beforeunload',stopRecording);render();

let transcriptionWorker=null,pendingTranscription=null,jobId=0;
function getWorker(){
 if(!transcriptionWorker){
  transcriptionWorker=new Worker('./transcription-worker.js',{type:'module'});
  transcriptionWorker.onmessage=({data})=>{
   const job=pendingTranscription;if(!job||job.id!==data.id)return;
   if(job.session===session){
    if(data.type==='progress')recordStatus.textContent=data.status==='progress'?`מוריד מודל למכשיר: ${Math.round(data.progress)}% (${data.file})`:'טוען מודל תמלול חינמי למכשיר. בפעם הראשונה נדרש חיבור לאינטרנט…';
    if(data.type==='running')recordStatus.textContent='מתמלל בשפה שנבחרה במכשיר… אפשר להמתין; ההקלטה אינה נשלחת לשרת.';
   }
   if(data.type==='result'){pendingTranscription=null;job.resolve(data.text)}
   if(data.type==='error'){pendingTranscription=null;job.reject(new Error(data.message))}
  };
  transcriptionWorker.onerror=()=>{
   if(pendingTranscription){pendingTranscription.reject(new Error('לא ניתן לטעון את מודל התמלול. בדקו חיבור לאינטרנט ונסו בדפדפן מעודכן.'));pendingTranscription=null}
   transcriptionWorker.terminate();transcriptionWorker=null;
  };
 }
 return transcriptionWorker;
}
async function decodeRecording(dataUrl){
 const raw=atob(dataUrl.split(',')[1]);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));
 const AudioCtx=window.AudioContext||window.webkitAudioContext;
 if(!AudioCtx)throw new Error('הדפדפן אינו תומך בפענוח שמע. נסו Chrome או Edge מעודכן.');
 const context=new AudioCtx();let decoded;
 try{decoded=await context.decodeAudioData(bytes.buffer)}finally{await context.close()}
 const offline=new OfflineAudioContext(1,Math.ceil(decoded.duration*16000),16000);
 const source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start();
 const pcm=(await offline.startRendering()).getChannelData(0);
 if(!pcm.length||!pcm.some(x=>Math.abs(x)>0.0001))throw new Error('לא נקלט קול בהקלטה. בדקו את המיקרופון והקליטו שוב.');
 return new Float32Array(pcm);
}
async function transcribeAudio(current=session){
 if(!recordedAudio||transcribing)return;
 transcribing=true;const modelSelect=document.getElementById('speechModel');const model=modelSelect.value;const language=document.getElementById('speechLanguage').value;const transcriptionClass=activeClassId();modelSelect.disabled=true;const button=document.getElementById('transcribe');button.disabled=true;recordStatus.textContent='מכין את ההקלטה לתמלול מקומי…';
 try{
 const pcm=await decodeRecording(recordedAudio);if(current!==session)return;
 const worker=getWorker();const id=++jobId;
 const text=String(await new Promise((resolve,reject)=>{pendingTranscription={id,session:current,resolve,reject};worker.postMessage({id,audio:pcm,model,language},[pcm.buffer])})).trim();
 if(current!==session)return;
 if(!text)throw new Error('לא זוהה דיבור בהקלטה. אפשר להשמיע אותה ולנסות שוב.');
 const details=form.elements.details;
 if(details.value.trim()&&details.value.trim()!==text&&!confirm('התמלול מוכן. להחליף את פירוט המשימה בתמלול ההקלטה?')){recordStatus.textContent='התמלול הושלם. הטקסט הקיים נשמר לפי בחירתכם.';return}
 details.value=text;if(typeof trackUsage==='function')trackUsage('transcription_used',transcriptionClass);recordStatus.textContent='✓ ההקלטה תומללה במכשיר. בדקו וערכו את פירוט המשימה לפני השמירה.';
 }catch(e){if(current===session)recordStatus.textContent='התמלול לא הושלם: '+e.message+' ההקלטה נשמרה להשמעה ולניסיון נוסף.'}
 finally{transcribing=false;button.disabled=false;modelSelect.disabled=false}
}
document.getElementById('transcribe').onclick=()=>transcribeAudio();

function openAttachment(photo){
 const viewer=el('dialog');viewer.style.cssText='width:95vw;max-width:1200px;max-height:90vh;overflow:auto';
 const close=el('button','סגירת הצילום','secondary');close.type='button';close.onclick=()=>viewer.close();
 const title=el('h2',photo.caption||photo.name||'חומר עזר');const img=el('img');img.src=photo.src;img.alt=title.textContent;img.style.cssText='display:block;max-width:100%;height:auto;margin-top:16px;cursor:zoom-in';
 const zoom=el('button','הגדלה לגודל המקורי','secondary');zoom.type='button';zoom.onclick=()=>{const enlarged=img.style.maxWidth==='none';img.style.maxWidth=enlarged?'100%':'none';zoom.textContent=enlarged?'הגדלה לגודל המקורי':'התאמה למסך';};
 viewer.append(title,close,zoom,img);viewer.addEventListener('close',()=>viewer.remove(),{once:true});document.body.append(viewer);viewer.showModal();
}

function editTeacherTask(r){if(!teacherPermission('can_update_lessons')){alert(t('אין הרשאה לעדכן שיעור בכיתה הזו.'));return}
 if(aiGenerating||transcribing||ocrBusy||resourcesLoading||photosLoading){alert('המתינו לסיום הפעולה הנוכחית.');return}
 document.getElementById('add').click();
 form.elements.lessonTopic.value=r.lesson?.topic||'';form.elements.lessonSummary.value=r.lesson?.summary||'';form.elements.lessonConcepts.value=r.lesson?.concepts||'';form.elements.subject.value=r.subject;form.elements.teacher.value=r.teacher;form.elements.kind.value=r.kind;form.elements.details.value=r.details||'';form.elements.details.required=r.kind==='task';form.elements.details.disabled=r.kind==='none';form.elements.due.value=r.due;form.elements.dueTime.value=r.dueTime||'08:00';
 recordedAudio=r.audio||null;if(recordedAudio){preview.src=recordedAudio;preview.hidden=false;document.getElementById('transcribe').hidden=false}
 boardPhotos=(r.photos||[]).map(p=>({...p}));showBoardPhotos();taskResources=(r.resources||[]).map(x=>({...x}));showResources();
 if(r.explanation){aiDraft.value=r.explanation.text;aiApprove.checked=r.explanation.status==='approved';if(aiApprove.checked)aiApprove.onchange();else document.getElementById('approvalStatus').textContent='טיוטה שמורה. בדקו וערכו לפני אישור.'}
}
